 static class TestClock extends Clock {final AtomicReference<Instant> now=new AtomicReference<>(Instant.parse("2030-01-31T17:00:00Z"));public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return Clock.fixed(now.get(),z);}public Instant instant(){return now.get();}}
 static final TestClock clock=new TestClock(); @TestConfiguration static class Time {@Bean @Primary Clock membershipTestClock(){return clock;}}
 @DynamicPropertySource static void ds(DynamicPropertyRegistry p){AccountIntegrationDatabase.prepare();p.add("spring.datasource.url",()->AccountIntegrationDatabase.env("ACCOUNT_HISTORY_DB_URL"));p.add("spring.datasource.username",()->"fitcenter_account_app");p.add("spring.datasource.password",()->AccountIntegrationDatabase.env("ACCOUNT_DB_PASSWORD"));p.add("fitcenter.account-integration.guard-verified",()->true);p.add("jwt.secret",HttpBaselineFixture::randomSecret);}
 @Autowired JdbcTemplate jdbc;@Autowired ObjectMapper json;@Autowired PasswordEncoder encoder;@LocalServerPort int port;
 HttpClient http;String admin,memberToken,ptToken;UUID plan;List<UUID> members=new ArrayList<>(),users=new ArrayList<>();String password=HttpBaselineFixture.randomSecret();
 void record(String table,UUID id){try{java.nio.file.Files.writeString(java.nio.file.Path.of(AccountIntegrationDatabase.env("ACCOUNT_PRIVATE_DIRECTORY"),"m03-test-ids-"+AccountIntegrationDatabase.nonce+".tsv"),table+"\t"+id+"\n",java.nio.file.StandardOpenOption.CREATE,java.nio.file.StandardOpenOption.APPEND);}catch(java.io.IOException e){throw new IllegalStateException("Cannot register test UUID");}}
 @BeforeAll void start()throws Exception{http=HttpClient.newHttpClient();var f=AccountIntegrationDatabase.fixture;admin=login(f.admin.email,f.admin.password);memberToken=login(f.memberA.email,f.memberA.password);ptToken=login(f.ptA.email,f.ptA.password);}
 @BeforeEach void before(){clock.now.set(Instant.parse("2030-01-31T17:00:00Z"));plan=UUID.randomUUID();record("membership_plans",plan);jdbc.update("INSERT INTO membership_plans(id,name,duration_days,price,status) VALUES(?,'Synthetic M03 plan',30,500000,'ACTIVE')",plan);}
 @AfterEach void cleanup(){for(UUID m:members){var ids=jdbc.queryForList("SELECT id FROM memberships WHERE member_id=?",UUID.class,m);for(UUID id:ids){jdbc.update("DELETE FROM audit_logs WHERE entity_type='MEMBERSHIP' AND entity_id=?",id);jdbc.update("DELETE FROM membership_initial_activations WHERE membership_id=? AND member_id=?",id,m);for(UUID pay:jdbc.queryForList("SELECT id FROM payment_transactions WHERE membership_id=? AND member_id=?",UUID.class,id,m))jdbc.update("DELETE FROM payment_transactions WHERE id=? AND member_id=?",pay,m);jdbc.update("DELETE FROM memberships WHERE id=? AND member_id=?",id,m);}jdbc.update("DELETE FROM members WHERE id=?",m);}for(UUID u:users)jdbc.update("DELETE FROM audit_logs WHERE entity_type='USER' AND entity_id=?",u);for(UUID u:users)jdbc.update("DELETE FROM users WHERE id=?",u);members.clear();users.clear();jdbc.update("DELETE FROM membership_plans WHERE id=?",plan);}
 @AfterAll void close(){http.close();}
 HttpResponse<String> call(String method,String path,String body,String token,String key)throws Exception{var b=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v1"+path)).timeout(Duration.ofSeconds(20)).header("Content-Type","application/json");if(token!=null)b.header("Authorization","Bearer "+token);if(key!=null)b.header("Idempotency-Key",key);return http.send(b.method(method,HttpRequest.BodyPublishers.ofString(body==null?"":body)).build(),HttpResponse.BodyHandlers.ofString());}
 @SuppressWarnings("unchecked") Map<String,Object> body(HttpResponse<String> r){return json.readValue(r.body(),Map.class);}
 void error(HttpResponse<String> r,int status,String code){assertEquals(status,r.statusCode());assertEquals(code,((Map<?,?>)body(r).get("error")).get("code"));assertFalse(r.body().contains("INSERT INTO"));assertTrue(r.headers().firstValue("X-Correlation-Id").isPresent());}
 String login(String e,String pw)throws Exception{var r=call("POST","/auth/login",json.writeValueAsString(Map.of("email",e,"password",pw)),null,null);assertEquals(200,r.statusCode());return (String)body(r).get("accessToken");}
 UUID member()throws Exception{var r=call("POST","/admin/members",json.writeValueAsString(Map.of("email","m03-"+UUID.randomUUID()+"@example.invalid","fullName","Synthetic M03 Member")),admin,null);assertEquals(201,r.statusCode());var a=body(r);UUID u=UUID.fromString((String)a.get("userId")),m=UUID.fromString((String)a.get("profileId"));users.add(u);members.add(m);record("users",u);record("members",m);jdbc.update("UPDATE users SET password_hash=? WHERE id=?",encoder.encode(password),u);return m;}
 String request(String receipt){return json.writeValueAsString(Map.of("planId",plan,"amountCollected",500000,"receiptRef",receipt));}
 HttpResponse<String> activate(UUID m,String key,String req)throws Exception{return call("POST","/admin/members/"+m+"/activate-membership",req,admin,key);}
 int count(String table,UUID member){return jdbc.queryForObject("SELECT count(*) FROM "+table+" WHERE member_id=?",Integer.class,member);}
 @Test void schemaEmptyAndHistoryPreserveAllPeriods(){var current=AccountIntegrationDatabase.snapshot(jdbc);current.get("membership_plans").removeIf(row->row.contains(plan.toString()));assertTrue(AccountIntegrationDatabase.before.equals(current),"Legacy rows and payment periods must be unchanged");assertEquals(0,new JdbcTemplate(AccountIntegrationDatabase.empty).queryForObject("SELECT count(*) FROM membership_initial_activations",Integer.class));assertEquals("1,2,3,4,5,6,8,9,10",jdbc.queryForObject("SELECT string_agg(version,',' ORDER BY installed_rank) FROM flyway_schema_history",String.class));assertEquals(6,AccountIntegrationDatabase.payments.size());}
 @Test void lateV7CannotBeSilentlyApplied()throws Exception{var path=java.nio.file.Path.of(AccountIntegrationDatabase.env("ACCOUNT_PRIVATE_DIRECTORY"),"v7-reference");var flyway=org.flywaydb.core.Flyway.configure().dataSource(AccountIntegrationDatabase.history).locations("classpath:db/migration","classpath:db/activation-rehearsal","classpath:db/membership-rehearsal","classpath:db/member-activation-rehearsal","filesystem:"+path).outOfOrder(false).cleanDisabled(true).load();assertThrows(FlywayException.class,flyway::migrate);assertEquals(2,jdbc.queryForObject("SELECT count(*) FROM information_schema.columns WHERE table_name='payment_transactions' AND column_name IN ('period_start','period_end')",Integer.class));}
 @Test void disabledMemberGetsMembershipButNoJwtAndNothingElseChanges()throws Exception{UUID m=member(),u=users.getLast();String before=jdbc.queryForObject("SELECT to_jsonb(u)::text FROM users u WHERE id=?",String.class,u);var booking=jdbc.queryForList("SELECT to_jsonb(b)::text FROM bookings b ORDER BY id",String.class);String key=UUID.randomUUID().toString();var r=activate(m,key,request("M03-"+m));assertEquals(201,r.statusCode());var dto=body(r);assertEquals(m.toString(),dto.get("memberId"));assertEquals(before,jdbc.queryForObject("SELECT to_jsonb(u)::text FROM users u WHERE id=?",String.class,u));assertEquals(booking,jdbc.queryForList("SELECT to_jsonb(b)::text FROM bookings b ORDER BY id",String.class));assertEquals(1,count("memberships",m));assertEquals(1,count("payment_transactions",m));assertEquals(1,count("membership_initial_activations",m));var read=call("GET","/admin/members/"+m+"/membership-activation",null,admin,null);assertEquals(dto,body(read));String email=jdbc.queryForObject("SELECT email FROM users WHERE id=?",String.class,u);error(call("POST","/auth/login",json.writeValueAsString(Map.of("email",email,"password",password)),null,null),401,"ERR_UNAUTHORIZED");}
 @Test void activeFixtureReadsThroughM04AndOtherMemberCannotSeeIt()throws Exception{UUID m=member(),u=users.getLast();jdbc.update("UPDATE users SET status='ACTIVE' WHERE id=?",u);String email=jdbc.queryForObject("SELECT email FROM users WHERE id=?",String.class,u),token=login(email,password);var r=activate(m,UUID.randomUUID().toString(),request("R-"+m));assertEquals(201,r.statusCode());var membership=(Map<?,?>)body(r).get("membership");var own=call("GET","/memberships/me",null,token,null);assertEquals(200,own.statusCode());assertEquals(List.of(membership),json.readValue(own.body(),List.class));assertFalse(call("GET","/memberships/me",null,memberToken,null).body().contains((String)membership.get("id")));}
 @ParameterizedTest @ValueSource(strings={"MEMBER","PT","NONE"}) void roles(String role)throws Exception{UUID m=member();error(call("POST","/admin/members/"+m+"/activate-membership",request("R-"+m),role.equals("MEMBER")?memberToken:role.equals("PT")?ptToken:null,UUID.randomUUID().toString()),role.equals("NONE")?401:403,role.equals("NONE")?"ERR_UNAUTHORIZED":"ERR_FORBIDDEN");}
 @ParameterizedTest @ValueSource(strings={"ACTIVE","PENDING_ACTIVATION","EXPIRED","SUSPENDED","CANCELLED"}) void anyHistoryBlocksInitial(String state)throws Exception{UUID m=member(),id=UUID.randomUUID();jdbc.update("INSERT INTO memberships(id,member_id,plan_id,start_date,expiry_date,status) VALUES(?,?,?,'2020-01-01','2020-01-30',?)",id,m,plan,state);error(activate(m,UUID.randomUUID().toString(),request("R-"+m)),409,"ERR_MEMBERSHIP_ALREADY_EXISTS");assertEquals(0,count("payment_transactions",m));}
 @ParameterizedTest @CsvSource({"2028-02-28T17:00:00Z,1,2028-02-29,2028-02-29","2028-02-28T16:59:59Z,2,2028-02-28,2028-02-29","2029-12-31T17:00:00Z,30,2030-01-01,2030-01-30","2030-01-30T17:00:00Z,30,2030-01-31,2030-03-01"})
 void vietnamInclusiveBoundaries(String instant,int days,String start,String end)throws Exception{UUID m=member();clock.now.set(Instant.parse(instant));jdbc.update("UPDATE membership_plans SET duration_days=? WHERE id=?",days,plan);var r=activate(m,UUID.randomUUID().toString(),request("R-"+m));assertEquals(201,r.statusCode());var ms=(Map<?,?>)body(r).get("membership");assertEquals(start,ms.get("startDate"));assertEquals(end,ms.get("endDate"));assertEquals(java.sql.Date.valueOf(end),jdbc.queryForObject("SELECT period_end FROM payment_transactions WHERE member_id=?",java.sql.Date.class,m));}
 @Test void zeroAndReplayAfterDatePriceAndStatusChanges()throws Exception{UUID m=member();jdbc.update("UPDATE membership_plans SET price=0 WHERE id=?",plan);String req=request("  ref-"+m+"  ").replace("500000","0"),key=UUID.randomUUID().toString();var first=activate(m,key,req);assertEquals(201,first.statusCode());clock.now.set(Instant.parse("2031-01-01T00:00:00Z"));jdbc.update("UPDATE membership_plans SET price=100,duration_days=1,status='INACTIVE' WHERE id=?",plan);var next=activate(m,key,req);assertEquals(200,next.statusCode());assertEquals(body(first),body(next));assertEquals("true",next.headers().firstValue("Idempotency-Replayed").orElse(""));assertEquals(1,count("payment_transactions",m));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM audit_logs WHERE action='MEMBERSHIP_INITIAL_ACTIVATED' AND entity_id=?",Integer.class,UUID.fromString((String)((Map<?,?>)body(first).get("membership")).get("id"))));}
