 @Test void receiptAndNoteBoundaries()throws Exception{UUID m=member();for(String ref:List.of(" ","x".repeat(101)))error(activate(m,UUID.randomUUID().toString(),request(ref)),400,"ERR_VALIDATION");String req=json.writeValueAsString(Map.of("planId",plan,"amountCollected",500000,"receiptRef","R-"+m,"note","x".repeat(501)));error(activate(m,UUID.randomUUID().toString(),req),400,"ERR_VALIDATION");req=json.writeValueAsString(Map.of("planId",plan,"amountCollected",500000,"receiptRef","R".repeat(100),"note","x".repeat(500)));assertEquals(201,activate(m,UUID.randomUUID().toString(),req).statusCode());}
 @ParameterizedTest @ValueSource(strings={"ACTIVE","SUSPENDED","DISABLED"}) void memberStatusIsNotActivationRequirement(String status)throws Exception{UUID m=member(),u=users.getLast();jdbc.update("UPDATE users SET status=? WHERE id=?",status,u);String before=jdbc.queryForObject("SELECT to_jsonb(u)::text FROM users u WHERE id=?",String.class,u);assertEquals(201,activate(m,UUID.randomUUID().toString(),request("R-"+m)).statusCode());assertTrue(before.equals(jdbc.queryForObject("SELECT to_jsonb(u)::text FROM users u WHERE id=?",String.class,u)),"User must remain byte-identical");}
 @Test void adminDisabledWhileWaitingIsRejected()throws Exception{UUID actor=UUID.randomUUID();users.add(actor);record("users",actor);String email="m03-admin-"+actor+"@example.invalid";jdbc.update("INSERT INTO users(id,email,password_hash,role,status) VALUES(?,?,?,'ADMIN','ACTIVE')",actor,email,encoder.encode(password));String old=admin;admin=login(email,password);try{UUID m=member();var rs=race(List.of(m),List.of(()->activate(m,UUID.randomUUID().toString(),request("R-"+m))),()->jdbc.update("UPDATE users SET status='DISABLED' WHERE id=?",actor));error(rs.getFirst(),403,"ERR_FORBIDDEN");assertEquals(0,count("memberships",m));}finally{admin=old;}}
 @Test void sameKeyDifferentMembersRollsBackLoser()throws Exception{UUID a=member(),b=member();String key=UUID.randomUUID().toString(),req=request("K-"+a);var rs=race(List.of(a,b),List.of(()->activate(a,key,req),()->activate(b,key,req)),()->{});assertEquals(List.of(201,409),rs.stream().map(HttpResponse::statusCode).sorted().toList());assertEquals(1,count("payment_transactions",a)+count("payment_transactions",b));}
